{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C12"],
      "claim": "6-Fluoro-tryptophan, the highest-transfer analogue, achieved high rat brain concentrations (hypothalamus 9436 ng/g; cortex 3873 ng/g) via transporter-mediated BBB transport, showing that a polar fluorinated indole amino acid can have meaningful CNS access.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "CA140, a secondary-amine-containing compound, showed a brain-to-plasma ratio of 1.91 and was explicitly rated as good brain penetration, supporting CNS access for basic amine/heteroaromatic structures.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "MDMA, which contains the methylaminomethyl aryl motif also present in the query, showed clearly favored brain accumulation in rats and up to 30-fold higher human brain than blood levels, directly supporting CNS penetration of this motif.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Alsterpaullone, a fused heterocyclic ketone/lactam-type compound, was detected in brain after systemic administration, supporting that the query's fused lactam heterocycle can cross the BBB.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "Compound 7, a fluorinated fused heteroaromatic, showed good brain uptake in mouse (>4% ID/g) and NHP PET (1.8% whole brain peak), supporting CNS access for fluorinated fused heteroaromatic scaffolds.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "Sembragiline, a brain-targeted heteroaromatic amide, was confirmed by human PET to cross the BBB and inhibit brain MAO-B, providing translational evidence that similar drug-like heteroaromatic amides achieve meaningful CNS exposure.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All high-transfer experimental analogues demonstrate meaningful BBB penetration across rat, mouse, NHP, sheep, and human, including compounds sharing the methylaminomethyl aryl, fluorinated fused heteroaromatic, and lactam/amide features of the query. No contradictory evidence was retrieved. Therefore the query is predicted to have meaningful CNS access.",
  "evidence_gaps": [
    "No direct brain/plasma or CSF PK measurement for the query molecule itself.",
    "Efflux transporter (P-gp/BCRP) susceptibility of the query was not directly assessed.",
    "Unbound brain-to-plasma ratio and functional target engagement were not measured."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

